INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000b5',1,'APPROVED','PUBLISHED',
'{"objectives":["Give compliments in German","Respond to compliments","Use Das steht dir gut"],"explanation":{"intro":"Compliments are an important part of social language. German compliments tend to be sincere and specific — Germans don''t give empty flattery.","culturalNote":"Germans are more reserved with compliments than English speakers. Receiving a compliment, a modest response is common: Danke, das ist nett von Ihnen (Thank you, that''s kind of you) or Ach, das ist doch nicht so besonders (Oh, it''s nothing special really)."},"examples":[{"german":"Das steht dir wirklich gut!","english":"That really suits you!"},{"german":"Du sprichst Deutsch sehr gut für jemanden, der erst ein Jahr lernt.","english":"You speak German very well for someone who has only been learning for a year."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can give and receive compliments in German."}}',
'{"items":[{"word":"Das steht dir gut","translation":"That suits you","pronunciation":"dahs SHTAYT deer goot","example":"Das steht dir gut!"},{"word":"schmeicheln","translation":"to flatter","pronunciation":"SHMY-kheln","example":"Das schmeichelt mir."},{"word":"nett von dir","translation":"nice of you","pronunciation":"NET fon deer","example":"Das ist nett von dir."},{"word":"bewundern","translation":"to admire","pronunciation":"beh-VOON-dern","example":"Ich bewundere dich."},{"word":"Das gefällt mir an dir","translation":"I like that about you","pronunciation":"dahs geh-FÄLT meer an deer","example":"Das gefällt mir an dir."},{"word":"bescheiden","translation":"modest","pronunciation":"beh-SHY-den","example":"Sei nicht so bescheiden!"}]}',
'{"title":"Stehen — to suit (dative)","pattern":"Das steht dir/Ihnen/ihm gut (it suits you/him)","explanation":"Stehen (to stand) also means to suit. Das steht dir gut = that suits you (dative). Das Hemd steht ihm nicht = the shirt doesn''t suit him. Like gefallen and other dative verbs, the person is in dative (dir, ihm, ihr, Ihnen). Compare: Passen (to fit): Die Hose passt mir nicht (the trousers don''t fit me).","examples":[{"sentence":"Die Frisur steht ihr ausgezeichnet.","translation":"The hairstyle suits her excellently."},{"sentence":"Dieses Blau steht dir sehr gut.","translation":"This blue suits you very well."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Bescheiden'' means?","options":["modest","reserved","quiet","humble"],"correctAnswer":"modest"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"That really suits you!","options":["Das steht dir wirklich gut!","Das passt dir gut.","Das sieht schön aus.","Du siehst gut aus."],"correctAnswer":"Das steht dir wirklich gut!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Frisur steht ___ ausgezeichnet.","options":["ihr","sie","ihre","ihr"],"correctAnswer":"ihr"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This blue suits you very well","wordBankItems":["Dieses","Blau","steht","dir","sehr","gut","."],"correctAnswer":"Dieses Blau steht dir sehr gut ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Stehen'' meaning to suit takes which case?","options":["dative","accusative","nominative","genitive"],"correctAnswer":"dative"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000b6',1,'APPROVED','PUBLISHED',
'{"objectives":["Apologise in different situations","Use Es tut mir leid","Know formal vs informal sorry"],"explanation":{"intro":"Apologies are essential for everyday interaction. German has different levels of apology from casual to formal.","culturalNote":"Es tut mir leid is a genuine apology. Entschuldigung is more like excuse me. For serious matters: Ich möchte mich aufrichtig entschuldigen (I sincerely apologise). Germans appreciate direct, clear apologies rather than circuitous ones."},"examples":[{"german":"Es tut mir wirklich leid, das war mein Fehler.","english":"I am truly sorry, that was my fault."},{"german":"Ich möchte mich für meine Verspätung entschuldigen.","english":"I would like to apologise for my lateness."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can apologise and express regret in different situations in German."}}',
'{"items":[{"word":"Es tut mir leid","translation":"I am sorry","pronunciation":"es toot meer lyt","example":"Es tut mir leid!"},{"word":"der Fehler","translation":"mistake/error","pronunciation":"dayr FEY-ler","example":"Das war mein Fehler."},{"word":"sich entschuldigen","translation":"to apologise","pronunciation":"zikh ent-SHOOL-dee-gen","example":"Ich entschuldige mich."},{"word":"vergeben","translation":"to forgive","pronunciation":"fer-GAY-ben","example":"Kannst du mir vergeben?"},{"word":"aufrichtig","translation":"sincere/genuine","pronunciation":"OWF-rikh-tikh","example":"Eine aufrichtige Entschuldigung."},{"word":"versehentlich","translation":"accidentally/by mistake","pronunciation":"fer-ZEY-ent-likh","example":"Versehentlich gemacht."}]}',
'{"title":"Sich entschuldigen für — to apologise for","pattern":"sich entschuldigen für + accusative noun phrase","explanation":"Sich entschuldigen für (to apologise for). Ich entschuldige mich für die Verspätung = I apologise for the lateness (accusative). Reflexive: mich (accusative, same person). Formal: Ich möchte mich... entschuldigen (I would like to apologise). Past: Ich habe mich entschuldigt = I apologised.","examples":[{"sentence":"Er hat sich für sein Verhalten entschuldigt.","translation":"He apologised for his behaviour."},{"sentence":"Ich entschuldige mich für den Lärm.","translation":"I apologise for the noise."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Versehentlich'' means?","options":["accidentally","unintentionally","carelessly","mistakenly"],"correctAnswer":"accidentally"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am truly sorry, that was my fault.","options":["Es tut mir wirklich leid, das war mein Fehler.","Ich bin traurig, das war ein Fehler.","Entschuldigung, mein Fehler.","Das tut mir leid."],"correctAnswer":"Es tut mir wirklich leid, das war mein Fehler."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich entschuldige mich für ___ Lärm.","options":["den","dem","der","das"],"correctAnswer":"den"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He apologised for his behaviour","wordBankItems":["Er","hat","sich","für","sein","Verhalten","entschuldigt","."],"correctAnswer":"Er hat sich für sein Verhalten entschuldigt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vergeben'' means?","options":["to forgive","to give","to hand over","to pardon"],"correctAnswer":"to forgive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000b7',1,'APPROVED','PUBLISHED',
'{"objectives":["Give advice in German","Use Du solltest / An deiner Stelle","Respond to requests for advice"],"explanation":{"intro":"Giving advice is a key social language function. German has several structures for different levels of directness.","culturalNote":"Germans value direct, clear advice. Wishy-washy advice is often seen as unhelpful. At the same time, unsolicited advice (Ratschläge) can be unwelcome — waiting to be asked is polite."},"examples":[{"german":"Du solltest mehr Wasser trinken.","english":"You should drink more water."},{"german":"An deiner Stelle würde ich zum Arzt gehen.","english":"In your place I would go to the doctor."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can give advice using several German structures."}}',
'{"items":[{"word":"Du solltest","translation":"You should (advice)","pronunciation":"doo ZOLTEST","example":"Du solltest schlafen."},{"word":"an deiner Stelle","translation":"in your place","pronunciation":"an DY-ner SHTEL-eh","example":"An deiner Stelle..."},{"word":"es wäre besser, wenn","translation":"it would be better if","pronunciation":"es VÄ-reh BES-er VEN","example":"Es wäre besser, wenn."},{"word":"ich rate dir zu","translation":"I advise you to","pronunciation":"ikh RAH-teh deer TSOO","example":"Ich rate dir dazu."},{"word":"du könntest","translation":"you could","pronunciation":"doo KÖN-test","example":"Du könntest versuchen."},{"word":"auf jeden Fall","translation":"in any case/definitely","pronunciation":"owf YAY-den FAL","example":"Auf jeden Fall gehen."}]}',
'{"title":"An deiner Stelle würde ich — in your place","pattern":"An deiner/Ihrer Stelle würde ich + infinitive","explanation":"An deiner Stelle = in your place (literally: at your position). Würde ich + infinitive = would I (Konjunktiv II). An deiner Stelle würde ich das nicht tun = In your place I wouldn''t do that. Very useful, empathetic advice structure. Formal: An Ihrer Stelle würde ich...","examples":[{"sentence":"An deiner Stelle würde ich mit dem Chef sprechen.","translation":"In your place I would speak with the boss."},{"sentence":"An Ihrer Stelle würde ich einen Anwalt nehmen.","translation":"In your place I would get a lawyer."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ich rate dir zu'' means?","options":["I advise you to","I recommend you","I suggest you","I tell you to"],"correctAnswer":"I advise you to"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In your place I would go to the doctor.","options":["An deiner Stelle würde ich zum Arzt gehen.","Du solltest zum Arzt gehen.","Ich würde zum Arzt gehen.","Geh zum Arzt!"],"correctAnswer":"An deiner Stelle würde ich zum Arzt gehen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Du ___ mehr Wasser trinken.","options":["solltest","sollst","würdest","kannst"],"correctAnswer":"solltest"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In your place I would speak with the boss","wordBankItems":["An","deiner","Stelle","würde","ich","mit","dem","Chef","sprechen","."],"correctAnswer":"An deiner Stelle würde ich mit dem Chef sprechen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Auf jeden Fall'' means?","options":["in any case/definitely","in this case","whatever happens","by all means"],"correctAnswer":"in any case/definitely"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000b8',1,'APPROVED','PUBLISHED',
'{"objectives":["Express opinions clearly","Use Meiner Meinung nach","Agree and disagree politely"],"explanation":{"intro":"Expressing opinions is a fundamental conversational skill. A2 covers core opinion phrases.","culturalNote":"Germans are known for expressing opinions directly. Ich finde (I find) and Ich meine (I think) are common opinion starters. Public debate (Diskussionskultur) is valued — having a clear, justified opinion is respected."},"examples":[{"german":"Meiner Meinung nach ist das eine gute Idee.","english":"In my opinion that is a good idea."},{"german":"Ich bin anderer Meinung — das halte ich für falsch.","english":"I disagree — I consider that to be wrong."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can express and justify opinions in German."}}',
'{"items":[{"word":"meiner Meinung nach","translation":"in my opinion","pronunciation":"MY-ner MY-noong NAKH","example":"Meiner Meinung nach."},{"word":"Ich bin anderer Meinung","translation":"I disagree/I hold a different view","pronunciation":"ikh bin AN-der-er MY-noong","example":"Ich bin anderer Meinung."},{"word":"halten für","translation":"to consider/regard as","pronunciation":"HAL-ten FÜR","example":"Das halte ich für richtig."},{"word":"ich finde","translation":"I find/think","pronunciation":"ikh FIN-deh","example":"Ich finde das gut."},{"word":"überzeugend","translation":"convincing","pronunciation":"ü-ber-TSOY-gend","example":"Das ist überzeugend."},{"word":"einverstanden","translation":"in agreement/okay","pronunciation":"YN-fer-shtan-den","example":"Da bin ich einverstanden."}]}',
'{"title":"Meiner Meinung nach — opinion phrases","pattern":"Meiner Meinung nach + main clause (verb in position 2)","explanation":"Meiner Meinung nach (in my opinion) = dative possessive. After this phrase, verb stays in position 2: Meiner Meinung nach ist das richtig. Alternatives: Ich finde, dass... / Ich denke, dass... / Ich bin der Meinung, dass... All introduce a subordinate clause with verb at end.","examples":[{"sentence":"Ich finde, dass wir mehr Zeit brauchen.","translation":"I think that we need more time."},{"sentence":"Meiner Ansicht nach ist das Problem lösbar.","translation":"In my view the problem is solvable."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Überzeugend'' means?","options":["convincing","interesting","impressive","persuasive"],"correctAnswer":"convincing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In my opinion that is a good idea.","options":["Meiner Meinung nach ist das eine gute Idee.","Ich denke, das ist gut.","Das ist meiner Meinung nach gut.","Ich finde das gut."],"correctAnswer":"Meiner Meinung nach ist das eine gute Idee."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich finde, ___ wir mehr Zeit brauchen.","options":["dass","weil","ob","wenn"],"correctAnswer":"dass"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I think that we need more time","wordBankItems":["Ich","finde",",","dass","wir","mehr","Zeit","brauchen","."],"correctAnswer":"Ich finde , dass wir mehr Zeit brauchen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"After ''meiner Meinung nach'', the verb is in what position?","options":["position 2","position 1","end of clause","after subject"],"correctAnswer":"position 2"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000b9',1,'APPROVED','PUBLISHED',
'{"objectives":["Hold a discussion in German","Use einerseits/andererseits","Interrupt and take the floor politely"],"explanation":{"intro":"Discussion language allows you to participate in conversations beyond simple statements.","culturalNote":"German discussions value Sachlichkeit (objectivity) — discussions should focus on arguments, not on personal attacks. Diskussionskultur (culture of debate) is taught in schools."},"examples":[{"german":"Einerseits hat er Recht, andererseits sehe ich das Problem.","english":"On the one hand he is right, on the other hand I see the problem."},{"german":"Darf ich kurz unterbrechen?","english":"May I just interrupt?"}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can participate in a structured discussion in German."}}',
'{"items":[{"word":"einerseits...andererseits","translation":"on one hand...on the other","pronunciation":"EY-ner-zyts...AN-der-er-zyts","example":"Einerseits...andererseits."},{"word":"unterbrechen","translation":"to interrupt","pronunciation":"OON-ter-bre-khen","example":"Darf ich unterbrechen?"},{"word":"das Argument","translation":"argument/point","pronunciation":"dahs ar-goo-MENT","example":"Ein gutes Argument."},{"word":"überzeugen","translation":"to convince","pronunciation":"ü-ber-TSOY-gen","example":"Das überzeugt mich nicht."},{"word":"zum Thema kommen","translation":"to get to the point","pronunciation":"tsoom TAY-mah KOM-en","example":"Kommen wir zum Thema."},{"word":"mit einem Wort","translation":"in a word/in short","pronunciation":"mit EY-nem VORT","example":"Mit einem Wort: Nein."}]}',
'{"title":"Einerseits...andererseits — balanced arguments","pattern":"Einerseits + [pro argument], andererseits + [counter argument]","explanation":"Einerseits...andererseits (on one hand...on the other) allows balanced arguments. Both halves have normal main clause order: Einerseits ist es günstig, andererseits ist die Qualität schlecht = On one hand it''s cheap, on the other the quality is bad. Often combined with jedoch (however): Einerseits..., jedoch andererseits...","examples":[{"sentence":"Einerseits spare ich Zeit, andererseits verliere ich Qualität.","translation":"On one hand I save time, on the other I lose quality."},{"sentence":"Das Thema hat einerseits Vorteile.","translation":"The topic has advantages on one hand."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Überzeugen'' means?","options":["to convince","to persuade","to argue","to justify"],"correctAnswer":"to convince"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"On the one hand he is right, on the other I see the problem.","options":["Einerseits hat er Recht, andererseits sehe ich das Problem.","Er hat Recht, aber ich sehe ein Problem.","Einerseits ja, andererseits nein.","Das Problem ist andererseits."],"correctAnswer":"Einerseits hat er Recht, andererseits sehe ich das Problem."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Darf ich kurz ___?","options":["unterbrechen","sprechen","reden","fragen"],"correctAnswer":"unterbrechen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: On one hand I save time on the other I lose quality","wordBankItems":["Einerseits","spare","ich","Zeit",",","andererseits","verliere","ich","Qualität","."],"correctAnswer":"Einerseits spare ich Zeit , andererseits verliere ich Qualität ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Mit einem Wort'' means?","options":["in a word/in short","with a word","in one sentence","to summarise"],"correctAnswer":"in a word/in short"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000ba',1,'APPROVED','PUBLISHED',
'{"objectives":["Narrate past events","Use Imperfekt for narrative","Combine Perfekt and Imperfekt"],"explanation":{"intro":"Telling stories and narrating past events uses both Perfekt (conversational past) and Imperfekt (narrative past). A2 introduces this distinction.","culturalNote":"In spoken German, Perfekt is the standard past tense in most regions. However, war (was) and hatte (had) are universally used even in conversation. Southern German dialects use Perfekt almost exclusively; Northern Germany uses more Imperfekt."},"examples":[{"german":"Als ich jung war, haben wir jeden Sommer im See geschwommen.","english":"When I was young, we swam in the lake every summer."},{"german":"Früher hatte ich keine Zeit für Hobbys.","english":"In the past I had no time for hobbies."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can narrate past events using appropriate tenses in German."}}',
'{"items":[{"word":"früher","translation":"in the past/formerly","pronunciation":"FRÜ-er","example":"Früher war es anders."},{"word":"damals","translation":"at that time/back then","pronunciation":"DAH-mahls","example":"Damals war ich jung."},{"word":"eines Tages","translation":"one day","pronunciation":"EY-nes TAH-ges","example":"Eines Tages passierte."},{"word":"auf einmal","translation":"suddenly/all of a sudden","pronunciation":"owf EY-nmal","example":"Auf einmal war er weg."},{"word":"seitdem","translation":"since then","pronunciation":"ZYT-dem","example":"Seitdem ist alles anders."},{"word":"rückblickend","translation":"looking back","pronunciation":"RÜK-blik-end","example":"Rückblickend war es richtig."}]}',
'{"title":"Früher + Imperfekt — habitual past","pattern":"Früher + war/hatte/verb-Imperfekt (used to / in the past)","explanation":"Früher + Imperfekt describes past habits and states. Früher hatte ich... = I used to have... Früher wohnte ich... = I used to live... German doesn''t have a direct used to construction — früher + past tense covers this. Damals (at that time) + Imperfekt is also common for narrative.","examples":[{"sentence":"Früher wohnten wir in einer kleinen Wohnung.","translation":"We used to live in a small flat."},{"sentence":"Damals hatte ich einen anderen Job.","translation":"At that time I had a different job."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Auf einmal'' means?","options":["suddenly","at once","in one go","at the same time"],"correctAnswer":"suddenly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In the past I had no time for hobbies.","options":["Früher hatte ich keine Zeit für Hobbys.","Ich hatte keine Zeit.","Damals hatte ich Hobbys.","Früher keine Hobbys."],"correctAnswer":"Früher hatte ich keine Zeit für Hobbys."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Früher ___ wir in einer kleinen Wohnung.","options":["wohnten","haben gewohnt","hatten gewohnt","wohnen"],"correctAnswer":"wohnten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: At that time I had a different job","wordBankItems":["Damals","hatte","ich","einen","anderen","Job","."],"correctAnswer":"Damals hatte ich einen anderen Job ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Seitdem'' means?","options":["since then","from then","at that time","afterwards"],"correctAnswer":"since then"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000bb',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about future plans in detail","Use vorhaben, planen, beabsichtigen","Discuss near and distant future"],"explanation":{"intro":"Future plans vocabulary goes beyond simple werden to more nuanced planning language.","culturalNote":"Germans are known for careful long-term planning (Langzeitplanung). Appointment books (Terminkalender) are taken seriously. Spontaneous plans are possible but scheduling in advance is the norm."},"examples":[{"german":"Ich habe vor, nächstes Jahr nach Japan zu reisen.","english":"I intend to travel to Japan next year."},{"german":"In fünf Jahren möchte ich ein eigenes Unternehmen haben.","english":"In five years I would like to have my own company."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about future plans using a range of German structures."}}',
'{"items":[{"word":"vorhaben","translation":"to intend/plan","pronunciation":"FOR-hah-ben","example":"Ich habe vor."},{"word":"planen","translation":"to plan","pronunciation":"PLAH-nen","example":"Ich plane eine Reise."},{"word":"beabsichtigen","translation":"to intend (formal)","pronunciation":"beh-AP-zikh-tee-gen","example":"Ich beabsichtige."},{"word":"in fünf Jahren","translation":"in five years","pronunciation":"in FÜNF YAH-ren","example":"In fünf Jahren."},{"word":"das eigene Unternehmen","translation":"one''s own company","pronunciation":"dahs EY-geh-neh OON-ter-neh-men","example":"Ein eigenes Unternehmen."},{"word":"langfristig","translation":"long-term","pronunciation":"LANG-fris-tikh","example":"Langfristige Pläne."}]}',
'{"title":"In + time frame — future time expressions","pattern":"in + dative time: in einem Jahr, in drei Monaten, in fünf Jahren","explanation":"In + dative for future time frames. In einem Jahr = in a year. In drei Monaten = in three months. In fünf Jahren = in five years. In einer Woche = in a week. These always use dative: einem (m/n), einer (f), and plural nouns + -n (Jahren not *Jahre). Compare with English: in five years = in fünf Jahren.","examples":[{"sentence":"In zwei Jahren werde ich meinen Abschluss machen.","translation":"In two years I will finish my degree."},{"sentence":"In einer Woche fliege ich nach London.","translation":"In a week I''m flying to London."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Langfristig'' means?","options":["long-term","long-lasting","extended","prolonged"],"correctAnswer":"long-term"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I intend to travel to Japan next year.","options":["Ich habe vor, nächstes Jahr nach Japan zu reisen.","Ich möchte nach Japan reisen.","Nächstes Jahr fliege ich nach Japan.","Ich plane Japan."],"correctAnswer":"Ich habe vor, nächstes Jahr nach Japan zu reisen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"In zwei Jahren werde ich meinen Abschluss ___.","options":["machen","gemacht","mache","machen werden"],"correctAnswer":"machen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In a week I am flying to London","wordBankItems":["In","einer","Woche","fliege","ich","nach","London","."],"correctAnswer":"In einer Woche fliege ich nach London ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Beabsichtigen'' means?","options":["to intend (formal)","to plan","to decide","to consider"],"correctAnswer":"to intend (formal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000bc',1,'APPROVED','PUBLISHED',
'{"objectives":["Express hopes and dreams","Use Ich hoffe, dass...","Use Träume vocabulary"],"explanation":{"intro":"Hopes and dreams vocabulary is useful for personal and social conversations. Talking about aspirations connects people.","culturalNote":"Träume (dreams) are a rich topic in German culture. There is a tradition of Lebensträume (life dreams) — big life goals. Realist and idealist impulses both exist in German culture."},"examples":[{"german":"Ich hoffe, dass ich irgendwann in Australien leben werde.","english":"I hope that I will live in Australia someday."},{"german":"Mein größter Traum ist, die ganze Welt zu bereisen.","english":"My biggest dream is to travel the whole world."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can express hopes and dreams in German."}}',
'{"items":[{"word":"hoffen","translation":"to hope","pronunciation":"HOP-fen","example":"Ich hoffe, dass."},{"word":"der Traum","translation":"dream","pronunciation":"dayr TROWM","example":"Mein größter Traum."},{"word":"träumen von","translation":"to dream of","pronunciation":"TROY-men fon","example":"Ich träume von."},{"word":"irgendwann","translation":"someday/sometime","pronunciation":"EER-gent-van","example":"Irgendwann."},{"word":"verwirklichen","translation":"to realise/fulfil (a dream)","pronunciation":"fer-VIRK-likh-en","example":"Einen Traum verwirklichen."},{"word":"bereisen","translation":"to travel through","pronunciation":"beh-RY-zen","example":"Die Welt bereisen."}]}',
'{"title":"Ich hoffe, dass — hope + subordinate clause","pattern":"Ich hoffe, dass + [verb-final clause]","explanation":"Hoffen dass (to hope that). Ich hoffe, dass es klappt = I hope that it works out. Verb goes to end in the dass-clause. Alternative: Ich hoffe zu + infinitive (same subject): Ich hoffe, irgendwann dort zu leben. Distinction: hoffe, dass (when subjects differ or you want to be explicit) vs. hoffe zu (same subject, shorter).","examples":[{"sentence":"Ich hoffe, dass du gesund bleibst.","translation":"I hope that you stay healthy."},{"sentence":"Wir hoffen auf gutes Wetter.","translation":"We are hoping for good weather."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verwirklichen'' means?","options":["to realise/fulfil","to achieve","to accomplish","to dream"],"correctAnswer":"to realise/fulfil"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I hope that I will live in Australia someday.","options":["Ich hoffe, dass ich irgendwann in Australien leben werde.","Ich möchte in Australien leben.","Irgendwann lebe ich in Australien.","Australien ist mein Traum."],"correctAnswer":"Ich hoffe, dass ich irgendwann in Australien leben werde."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich hoffe, ___ du gesund bleibst.","options":["dass","weil","ob","wenn"],"correctAnswer":"dass"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My biggest dream is to travel the whole world","wordBankItems":["Mein","größter","Traum","ist",",","die","ganze","Welt","zu","bereisen","."],"correctAnswer":"Mein größter Traum ist , die ganze Welt zu bereisen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bereisen'' means?","options":["to travel through","to visit","to explore","to tour"],"correctAnswer":"to travel through"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000bd',1,'APPROVED','PUBLISHED',
'{"objectives":["Make comparisons in German","Use genauso wie and viel/ein bisschen mehr","Discuss similarities and differences"],"explanation":{"intro":"Comparison structures allow more nuanced descriptions. A2 builds on basic comparatives.","culturalNote":"Comparisons are common in German everyday language. Comparing prices, distances, and quality is natural. German comparative structures are regular and predictable once you know the pattern."},"examples":[{"german":"Berlin ist fast genauso groß wie London.","english":"Berlin is almost as big as London."},{"german":"Das neue Handy ist viel besser als das alte.","english":"The new phone is much better than the old one."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can make detailed comparisons in German."}}',
'{"items":[{"word":"genauso...wie","translation":"just as...as","pronunciation":"geh-NOW-zo...vee","example":"Genauso groß wie."},{"word":"viel + Komparativ","translation":"much + comparative","pronunciation":"FEEL","example":"Viel besser."},{"word":"ein bisschen + Komparativ","translation":"a little + comparative","pronunciation":"yn BIS-khen","example":"Ein bisschen teurer."},{"word":"ungefähr genauso","translation":"approximately the same","pronunciation":"OON-geh-fähr geh-NOW-zo","example":"Ungefähr genauso."},{"word":"der Unterschied","translation":"difference","pronunciation":"dayr OON-ter-sheet","example":"Ein großer Unterschied."},{"word":"die Gemeinsamkeit","translation":"similarity","pronunciation":"dee geh-MYN-zahm-kyt","example":"Eine Gemeinsamkeit."}]}',
'{"title":"Genauso...wie — equality comparison","pattern":"genauso + adjective + wie (just as...as)","explanation":"Equality: genauso + adj + wie. Berlin ist genauso groß wie München = Berlin is just as big as Munich. Not as: nicht so + adj + wie. Berlin ist nicht so teuer wie London. Comparatives: viel (much), ein bisschen/etwas (a little) modify comparatives: viel besser, etwas günstiger.","examples":[{"sentence":"Sie spricht fast genauso gut Deutsch wie ich.","translation":"She speaks German almost as well as I do."},{"sentence":"Der neue Film ist nicht so interessant wie der alte.","translation":"The new film is not as interesting as the old one."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Gemeinsamkeit'' means?","options":["similarity","common ground","shared interest","likeness"],"correctAnswer":"similarity"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Berlin is almost as big as London.","options":["Berlin ist fast genauso groß wie London.","Berlin und London sind gleich groß.","Berlin ist fast so groß wie London.","Berlin ist kleiner als London."],"correctAnswer":"Berlin ist fast genauso groß wie London."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das neue Handy ist viel ___ als das alte.","options":["besser","gut","mehr","super"],"correctAnswer":"besser"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The new film is not as interesting as the old one","wordBankItems":["Der","neue","Film","ist","nicht","so","interessant","wie","der","alte","."],"correctAnswer":"Der neue Film ist nicht so interessant wie der alte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Unterschied'' means?","options":["difference","distinction","gap","contrast"],"correctAnswer":"difference"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000be',1,'APPROVED','PUBLISHED',
'{"objectives":["Name and describe emotions","Use emotional vocabulary","Describe what you feel and why"],"explanation":{"intro":"Emotional vocabulary is essential for authentic conversations. A2 builds a broader emotional vocabulary beyond basic happy/sad.","culturalNote":"Germans have a rich emotional vocabulary, including words with no direct English equivalent — Fernweh (yearning to travel), Schadenfreude (pleasure at others'' misfortune), Sehnsucht (deep yearning/longing). These reflect cultural attitudes."},"examples":[{"german":"Ich fühle mich überwältigt von der Situation.","english":"I feel overwhelmed by the situation."},{"german":"Es erfüllt mich mit Freude, Deutsch zu lernen.","english":"It fills me with joy to learn German."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can describe complex emotions and feelings in German."}}',
'{"items":[{"word":"überwältigt","translation":"overwhelmed","pronunciation":"ü-ber-VÄL-tikht","example":"Ich bin überwältigt."},{"word":"erfüllen mit","translation":"to fill with (feeling)","pronunciation":"er-FÜL-en mit","example":"Das erfüllt mich mit."},{"word":"die Sehnsucht","translation":"longing/yearning","pronunciation":"dee ZEYN-zoohkt","example":"Eine tiefe Sehnsucht."},{"word":"enttäuscht","translation":"disappointed","pronunciation":"ent-TOYSHT","example":"Ich bin enttäuscht."},{"word":"erleichtert","translation":"relieved","pronunciation":"er-LYK-tert","example":"Ich bin erleichtert."},{"word":"aufgeregt","translation":"excited/agitated","pronunciation":"OWF-geh-reykt","example":"Ich bin aufgeregt."}]}',
'{"title":"Es erfüllt mich — it fills me (dative structure)","pattern":"etwas erfüllt mich mit + emotion (something fills me with + emotion)","explanation":"Erfüllen mit = to fill with (an emotion). Es erfüllt mich mit Freude = It fills me with joy. Mit Stolz erfüllt sein = to be filled with pride. Other emotion structures: Ich fühle mich + adjective (I feel + adj). Mir ist + adjective (I feel + adj): Mir ist warm = I feel warm. Mich macht es glücklich = it makes me happy.","examples":[{"sentence":"Das Ergebnis hat mich mit Erleichterung erfüllt.","translation":"The result filled me with relief."},{"sentence":"Ich fühle mich heute viel besser.","translation":"I feel much better today."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erleichtert'' means?","options":["relieved","relaxed","eased","lightened"],"correctAnswer":"relieved"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I feel overwhelmed by the situation.","options":["Ich fühle mich überwältigt von der Situation.","Die Situation überwältigt mich.","Ich bin überwältigt.","Ich fühle mich schlecht."],"correctAnswer":"Ich fühle mich überwältigt von der Situation."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es erfüllt mich ___ Freude.","options":["mit","von","durch","bei"],"correctAnswer":"mit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The result filled me with relief","wordBankItems":["Das","Ergebnis","hat","mich","mit","Erleichterung","erfüllt","."],"correctAnswer":"Das Ergebnis hat mich mit Erleichterung erfüllt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Aufgeregt'' means?","options":["excited/agitated","nervous","happy","surprised"],"correctAnswer":"excited/agitated"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000bf',1,'APPROVED','PUBLISHED',
'{"objectives":["Write formal and informal letters","Use letter conventions","Know salutations and closings"],"explanation":{"intro":"Letter and email conventions in German have specific formal and informal structures.","culturalNote":"German formal letters still follow rigid conventions. Betreff (subject line) appears before the salutation in letters. Ending: Hochachtungsvoll (formal, somewhat archaic) or Mit freundlichen Grüßen (standard, widely used). Informal: Viele Grüße, Liebe Grüße."},"examples":[{"german":"Sehr geehrte Damen und Herren, ich schreibe Ihnen bezüglich...","english":"Dear Sir/Madam, I am writing to you regarding..."},{"german":"Liebe Maria, ich wollte dir kurz schreiben...","english":"Dear Maria, I just wanted to write to you briefly..."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can write both formal and informal letters in German."}}',
'{"items":[{"word":"Sehr geehrte/r","translation":"Dear (formal salutation)","pronunciation":"ZAYR geh-EHR-teh","example":"Sehr geehrter Herr."},{"word":"bezüglich","translation":"regarding/with regard to","pronunciation":"beh-TSÜK-likh","example":"Bezüglich Ihres Schreibens."},{"word":"Mit freundlichen Grüßen","translation":"Yours sincerely (MfG)","pronunciation":"mit FROYN-dlikh-en GRÜ-sen","example":"Mit freundlichen Grüßen."},{"word":"der Betreff","translation":"subject line (letter)","pronunciation":"dayr beh-TREF","example":"Betreff: Bewerbung."},{"word":"in der Anlage","translation":"enclosed/attached","pronunciation":"in dayr AN-lah-geh","example":"In der Anlage finden Sie."},{"word":"anbei","translation":"attached/enclosed (formal)","pronunciation":"AN-by","example":"Anbei sende ich."}]}',
'{"title":"Bezüglich + genitive — regarding","pattern":"bezüglich + genitive noun phrase","explanation":"Bezüglich (regarding/with regard to) + genitive. Bezüglich Ihres Schreibens (regarding your letter — Ihres = genitive possessive). Bezüglich der Bestellung (regarding the order). Common in formal business correspondence. Alternative: in Bezug auf + accusative (in reference to). Wegen (because of) is informal.","examples":[{"sentence":"Bezüglich Ihrer Anfrage teile ich mit...","translation":"Regarding your enquiry I inform you..."},{"sentence":"Anbei sende ich Ihnen meinen Lebenslauf.","translation":"Attached I am sending you my CV."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Anbei'' means?","options":["attached/enclosed","herewith","below","following"],"correctAnswer":"attached/enclosed"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Dear Sir/Madam, I am writing to you regarding...","options":["Sehr geehrte Damen und Herren, ich schreibe Ihnen bezüglich...","Hallo, ich schreibe über...","Guten Tag, ich wollte schreiben...","An wen es betrifft..."],"correctAnswer":"Sehr geehrte Damen und Herren, ich schreibe Ihnen bezüglich..."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bezüglich ___ Schreibens...","options":["Ihres","Ihrem","Ihren","Ihrer"],"correctAnswer":"Ihres"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Attached I am sending you my CV","wordBankItems":["Anbei","sende","ich","Ihnen","meinen","Lebenslauf","."],"correctAnswer":"Anbei sende ich Ihnen meinen Lebenslauf ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Standard formal letter closing in German is?","options":["Mit freundlichen Grüßen","Hochachtungsvoll","Herzliche Grüße","Tschüss"],"correctAnswer":"Mit freundlichen Grüßen"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c0',1,'APPROVED','PUBLISHED',
'{"objectives":["Handle complex phone calls","Leave a message","Use telephone phrases"],"explanation":{"intro":"Advanced phone vocabulary covers leaving messages, asking for callbacks and handling professional calls.","culturalNote":"Germans answer the phone by saying their surname or full name — not ''hello''. Unannounced calls are less common; WhatsApp messages are often sent first. Rückruf (callback) is expected if someone misses a call."},"examples":[{"german":"Könnten Sie ihm ausrichten, dass ich zurückgerufen habe?","english":"Could you let him know that I called back?"},{"german":"Ich rufe wegen eines Termins an.","english":"I am calling about an appointment."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can handle complex phone conversations and leave messages in German."}}',
'{"items":[{"word":"ausrichten","translation":"to pass on a message","pronunciation":"OWS-rikh-ten","example":"Können Sie ausrichten?"},{"word":"zurückrufen","translation":"to call back","pronunciation":"tsoo-RÜK-roo-fen","example":"Ich rufe zurück."},{"word":"wegen + genitive","translation":"because of/about (phone)","pronunciation":"VAY-gen","example":"Wegen eines Termins."},{"word":"der Rückruf","translation":"callback","pronunciation":"dayr RÜK-roof","example":"Einen Rückruf erbitten."},{"word":"in der Leitung","translation":"on the line","pronunciation":"in dayr LY-toong","example":"In der Leitung bleiben."},{"word":"die Nachricht hinterlassen","translation":"to leave a message","pronunciation":"dee NAKH-rikt hin-ter-LAS-en","example":"Eine Nachricht hinterlassen."}]}',
'{"title":"Könnten Sie ausrichten — passing messages","pattern":"Könnten Sie ihm/ihr ausrichten, dass + [verb-final clause]","explanation":"Ausrichten (pass on a message) = separable. Könnten Sie ihm ausrichten, dass... (Could you tell him that...). Indirect speech: dass + verb-final. Könnten Sie ihr sagen, dass ich morgen komme = Could you tell her I''m coming tomorrow. Formal polite: Ich würde Sie bitten, dass... = I would ask you to pass on that...","examples":[{"sentence":"Könnten Sie ihr ausrichten, dass ich heute Nachmittag anrufe?","translation":"Could you tell her that I will call this afternoon?"},{"sentence":"Ich hinterlasse eine Nachricht auf der Mailbox.","translation":"I will leave a message on voicemail."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausrichten'' means?","options":["to pass on a message","to arrange","to tell","to forward"],"correctAnswer":"to pass on a message"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am calling about an appointment.","options":["Ich rufe wegen eines Termins an.","Ich brauche einen Termin.","Ich rufe an.","Wegen dem Termin rufe ich an."],"correctAnswer":"Ich rufe wegen eines Termins an."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Könnten Sie ihr ausrichten, ___ ich morgen komme?","options":["dass","ob","wenn","weil"],"correctAnswer":"dass"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I will leave a message on voicemail","wordBankItems":["Ich","hinterlasse","eine","Nachricht","auf","der","Mailbox","."],"correctAnswer":"Ich hinterlasse eine Nachricht auf der Mailbox ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Germans typically answer the phone by saying?","options":["their surname","Hallo","Guten Tag","Ja?"],"correctAnswer":"their surname"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c1',1,'APPROVED','PUBLISHED',
'{"objectives":["Fill in German forms","Understand form vocabulary","Know common form fields"],"explanation":{"intro":"Filling in German forms is a practical life skill. Knowing field names prevents errors on official documents.","culturalNote":"Germany requires forms for almost everything — Ummeldung (address registration), Bafög (student support), Kindergeld (child benefit). Amtssprache (official language) is formal and precise."},"examples":[{"german":"Bitte füllen Sie das Formular vollständig aus.","english":"Please fill in the form completely."},{"german":"Geburtsort ist der Ort, wo Sie geboren wurden.","english":"Place of birth is the place where you were born."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can fill in and understand common German official forms."}}',
'{"items":[{"word":"das Formular ausfüllen","translation":"to fill in the form","pronunciation":"dahs for-moo-LAHR OWS-fül-en","example":"Das Formular ausfüllen."},{"word":"der Geburtsort","translation":"place of birth","pronunciation":"dayr geh-BURTS-ort","example":"Geburtsort eintragen."},{"word":"die Staatsangehörigkeit","translation":"nationality","pronunciation":"dee SHTAHTS-an-geh-hö-rikh-kyt","example":"Staatsangehörigkeit angeben."},{"word":"vollständig","translation":"complete/fully","pronunciation":"FOL-shtän-dikh","example":"Vollständig ausfüllen."},{"word":"eigenhändig","translation":"by hand/in person","pronunciation":"EY-gen-hän-dikh","example":"Eigenhändig unterschreiben."},{"word":"das Pflichtfeld","translation":"mandatory field","pronunciation":"dahs PFLIKT-felt","example":"Pflichtfelder ausfüllen."}]}',
'{"title":"Bitte + imperative — polite instructions","pattern":"Bitte + imperative (Sie form): Bitte füllen Sie aus / Bitte tragen Sie ein","explanation":"Polite instructions use Sie-imperative: Bitte füllen Sie das Formular aus. Bitte geben Sie Ihre Daten ein. Note: separable verbs split: füllen...aus, tragen...ein. Eintragen (to enter/fill in): Bitte tragen Sie Ihren Namen ein. Note on forms: in Druckbuchstaben (in capital letters) is common.","examples":[{"sentence":"Bitte unterschreiben Sie hier.","translation":"Please sign here."},{"sentence":"Tragen Sie Ihren Vor- und Zunamen ein.","translation":"Enter your first and last name."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Staatsangehörigkeit'' means?","options":["nationality","citizenship","identity","passport"],"correctAnswer":"nationality"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Please fill in the form completely.","options":["Bitte füllen Sie das Formular vollständig aus.","Füllen Sie das Formular aus.","Das Formular bitte ausfüllen.","Vollständig bitte."],"correctAnswer":"Bitte füllen Sie das Formular vollständig aus."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Tragen Sie Ihren Vor- und Zunamen ___.","options":["ein","aus","auf","ab"],"correctAnswer":"ein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please sign here","wordBankItems":["Bitte","unterschreiben","Sie","hier","."],"correctAnswer":"Bitte unterschreiben Sie hier ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vollständig'' means?","options":["complete/fully","correctly","carefully","clearly"],"correctAnswer":"complete/fully"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c2',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate German government offices","Know Amt and Behörde vocabulary","Handle Ummeldung etc."],"explanation":{"intro":"German bureaucracy has specific vocabulary for official institutions and processes.","culturalNote":"Germany''s Bürokratie (bureaucracy) is famous for thoroughness. Registration of address (Ummeldung/Anmeldung) is legally required within 14 days of moving. Einwohnermeldeamt (residents'' registration office) is the key office for newcomers."},"examples":[{"german":"Ich muss mich beim Einwohnermeldeamt anmelden.","english":"I have to register at the residents'' registration office."},{"german":"Bitte nehmen Sie eine Wartemarke.","english":"Please take a queue ticket."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can navigate German government offices and bureaucratic processes."}}',
'{"items":[{"word":"das Einwohnermeldeamt","translation":"residents'' registration office","pronunciation":"dahs EYN-voh-ner-mel-deh-amt","example":"Beim Einwohnermeldeamt."},{"word":"die Anmeldung","translation":"registration","pronunciation":"dee AN-mel-doong","example":"Die Anmeldung machen."},{"word":"die Wartemarke","translation":"queue ticket","pronunciation":"dee VAR-teh-mar-keh","example":"Eine Wartemarke nehmen."},{"word":"der Personalausweis","translation":"identity card","pronunciation":"dayr per-soh-NAHL-ows-vys","example":"Den Personalausweis vorzeigen."},{"word":"beglaubigt","translation":"certified/authenticated","pronunciation":"beh-GLOW-bikht","example":"Beglaubigte Kopie."},{"word":"die Ummeldung","translation":"change of address registration","pronunciation":"dee OOM-mel-doong","example":"Die Ummeldung vornehmen."}]}',
'{"title":"Sich anmelden bei — to register with","pattern":"sich anmelden bei + dative place/office","explanation":"Sich anmelden = to register/sign up. Bei + dative: bei dem Amt → beim Amt. Ich melde mich bei der Behörde an = I register with the authority. Separable: melde...an. Past: Ich habe mich angemeldet. Ummeldung = change of address registration. Abmeldung = deregistration.","examples":[{"sentence":"Man muss sich innerhalb von 14 Tagen anmelden.","translation":"One must register within 14 days."},{"sentence":"Ich habe mich beim Finanzamt angemeldet.","translation":"I have registered with the tax office."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Beglaubigt'' means?","options":["certified/authenticated","approved","signed","official"],"correctAnswer":"certified/authenticated"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have to register at the residents'' registration office.","options":["Ich muss mich beim Einwohnermeldeamt anmelden.","Ich melde mich an.","Ich gehe zum Amt.","Das Amt ist zuständig."],"correctAnswer":"Ich muss mich beim Einwohnermeldeamt anmelden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Man muss sich innerhalb von 14 Tagen ___.","options":["anmelden","angemeldet","melden","melden an"],"correctAnswer":"anmelden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please take a queue ticket","wordBankItems":["Bitte","nehmen","Sie","eine","Wartemarke","."],"correctAnswer":"Bitte nehmen Sie eine Wartemarke ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Ummeldung'' means?","options":["change of address registration","re-registration","address update","move notification"],"correctAnswer":"change of address registration"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c3',1,'APPROVED','PUBLISHED',
'{"objectives":["Handle banking vocabulary","Open an account","Discuss transactions"],"explanation":{"intro":"Banking vocabulary is practical for anyone living in Germany. Most transactions require a German bank account.","culturalNote":"Germany is known for preferring cash (Bargeld). Despite this, online banking (Online-Banking) and direct debit (SEPA-Lastschrift) are universal. Deutsche Bank, Sparkasse, and DKB are major banks."},"examples":[{"german":"Ich möchte ein Girokonto eröffnen.","english":"I would like to open a current account."},{"german":"Können Sie mir bitte den Kontostand mitteilen?","english":"Could you please tell me my account balance?"}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can handle basic banking in German."}}',
'{"items":[{"word":"das Girokonto","translation":"current account","pronunciation":"dahs GEER-oh-kon-toh","example":"Girokonto eröffnen."},{"word":"der Kontostand","translation":"account balance","pronunciation":"dayr KON-toh-shtant","example":"Den Kontostand prüfen."},{"word":"überweisen","translation":"to transfer (money)","pronunciation":"ü-ber-VY-zen","example":"Geld überweisen."},{"word":"die Überweisung","translation":"bank transfer","pronunciation":"dee ü-ber-VY-zoong","example":"Eine Überweisung machen."},{"word":"die IBAN","translation":"IBAN","pronunciation":"dee ee-BAN","example":"Die IBAN angeben."},{"word":"das Lastschriftverfahren","translation":"direct debit","pronunciation":"dahs LAST-shrift-fer-fah-ren","example":"Per Lastschrift."}]}',
'{"title":"Eröffnen — to open (an account)","pattern":"ein Konto eröffnen (to open an account)","explanation":"Eröffnen = to open (formally): ein Konto eröffnen (open an account), ein Geschäft eröffnen (open a business). Regular verb: ich eröffne, du eröffnest, er eröffnet. Past participle: eröffnet. Different from öffnen (open something physical). Kündigen = to close/cancel: ein Konto kündigen.","examples":[{"sentence":"Ich möchte mein Konto kündigen.","translation":"I would like to close my account."},{"sentence":"Das Konto wurde erfolgreich eröffnet.","translation":"The account was opened successfully."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Überweisen'' means?","options":["to transfer money","to send a payment","to wire","to remit"],"correctAnswer":"to transfer money"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would like to open a current account.","options":["Ich möchte ein Girokonto eröffnen.","Ich möchte ein Konto.","Ich eröffne ein Konto.","Ein Girokonto bitte."],"correctAnswer":"Ich möchte ein Girokonto eröffnen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Konto wurde erfolgreich ___.","options":["eröffnet","geöffnet","eröffnen","öffnen"],"correctAnswer":"eröffnet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Could you please tell me my account balance?","wordBankItems":["Können","Sie","mir","bitte","den","Kontostand","mitteilen","?"],"correctAnswer":"Können Sie mir bitte den Kontostand mitteilen ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ein Konto kündigen'' means?","options":["to close an account","to cancel a subscription","to end a contract","to terminate"],"correctAnswer":"to close an account"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c4',1,'APPROVED','PUBLISHED',
'{"objectives":["Understand insurance types","Discuss coverage","Use Versicherung vocabulary"],"explanation":{"intro":"Insurance is an important topic in Germany. Several types are legally required.","culturalNote":"Germany requires Krankenversicherung (health insurance) for all residents. Haftpflichtversicherung (liability insurance) is strongly recommended. Hausratversicherung (contents insurance) covers home possessions."},"examples":[{"german":"Eine Haftpflichtversicherung ist in Deutschland empfehlenswert.","english":"A liability insurance policy is advisable in Germany."},{"german":"Meine Krankenversicherung übernimmt die Kosten.","english":"My health insurance covers the costs."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss insurance types and coverage in German."}}',
'{"items":[{"word":"die Krankenversicherung","translation":"health insurance","pronunciation":"dee KRAN-ken-fer-zikh-roong","example":"Gesetzliche KV."},{"word":"die Haftpflicht","translation":"liability insurance","pronunciation":"dee HAFT-pflikt","example":"Haftpflicht abschließen."},{"word":"der Schaden","translation":"damage/claim","pronunciation":"dayr SHAH-den","example":"Einen Schaden melden."},{"word":"die Prämie","translation":"premium","pronunciation":"dee PREH-mee-eh","example":"Die Prämie zahlen."},{"word":"abschließen","translation":"to take out (insurance)","pronunciation":"AP-shlee-sen","example":"Eine Versicherung abschließen."},{"word":"übernehmen","translation":"to cover/take on","pronunciation":"ü-ber-NEY-men","example":"Die Kosten übernehmen."}]}',
'{"title":"Übernehmen — to cover/take on (costs)","pattern":"Die Versicherung übernimmt die Kosten (the insurance covers the costs)","explanation":"Übernehmen = to cover/take over. Die Versicherung übernimmt die Kosten = The insurance covers the costs. Ich übernehme das = I''ll take care of that / I''ll cover that. Strong verb: übernehmen → übernimmt → hat übernommen. Common in professional and administrative German.","examples":[{"sentence":"Die Versicherung hat die Reparaturkosten übernommen.","translation":"The insurance covered the repair costs."},{"sentence":"Wer übernimmt die Verantwortung?","translation":"Who takes responsibility?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Abschließen'' in context of insurance means?","options":["to take out","to conclude","to close","to sign"],"correctAnswer":"to take out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My health insurance covers the costs.","options":["Meine Krankenversicherung übernimmt die Kosten.","Ich habe Krankenversicherung.","Die Kosten sind gedeckt.","Versicherung zahlt."],"correctAnswer":"Meine Krankenversicherung übernimmt die Kosten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Versicherung hat die Reparaturkosten ___.","options":["übernommen","übernimmt","übernahm","übergenommen"],"correctAnswer":"übernommen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Who takes responsibility?","wordBankItems":["Wer","übernimmt","die","Verantwortung","?"],"correctAnswer":"Wer übernimmt die Verantwortung ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Schaden'' means?","options":["damage/claim","loss","accident","incident"],"correctAnswer":"damage/claim"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss sustainable living","Use Nachhaltigkeit vocabulary","Talk about reducing consumption"],"explanation":{"intro":"Sustainable living vocabulary is increasingly important and common in German conversations.","culturalNote":"Germany is a leader in green energy (Energiewende) and recycling (Mülltrennung). The concept of Nachhaltigkeit (sustainability) is mainstream. Fridays for Future had massive impact in Germany. Many Germans consciously reduce their Konsum (consumption)."},"examples":[{"german":"Ich versuche, meinen Plastikverbrauch zu reduzieren.","english":"I try to reduce my plastic consumption."},{"german":"Wir kaufen bevorzugt regionale Produkte.","english":"We prefer to buy regional products."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss sustainable living and environmental choices in German."}}',
'{"items":[{"word":"reduzieren","translation":"to reduce","pronunciation":"reh-doo-TSEER-en","example":"Verbrauch reduzieren."},{"word":"der Plastikverbrauch","translation":"plastic consumption","pronunciation":"dayr PLAS-tik-fer-browkh","example":"Plastik reduzieren."},{"word":"bevorzugt","translation":"preferably/by preference","pronunciation":"beh-for-TSOOKT","example":"Bevorzugt regional."},{"word":"die Mülltrennung","translation":"waste separation","pronunciation":"dee MÜL-tren-oong","example":"Mülltrennung betreiben."},{"word":"der ökologische Fußabdruck","translation":"ecological footprint","pronunciation":"dayr ö-koh-LOH-gish-eh FOOS-ap-drook","example":"Den Fußabdruck verringern."},{"word":"verringern","translation":"to reduce/diminish","pronunciation":"fer-RING-ern","example":"CO2 verringern."}]}',
'{"title":"Bevorzugt — preferably (adverb of preference)","pattern":"bevorzugt + verb phrase (preferably, by preference)","explanation":"Bevorzugt as adverb = preferably. Wir kaufen bevorzugt regional = We preferably buy regional (prefer to buy regional). Bevorzugen as verb = to prefer: Ich bevorzuge Bio-Produkte = I prefer organic products. Note: bevorzugt is participial adjective used as adverb — unusual but very common in sustainable lifestyle contexts.","examples":[{"sentence":"Sie kauft bevorzugt Second-Hand-Kleidung.","translation":"She preferably buys second-hand clothes."},{"sentence":"Bitte verwenden Sie bevorzugt wiederverwendbare Behälter.","translation":"Please preferably use reusable containers."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Mülltrennung'' means?","options":["waste separation","rubbish removal","garbage sorting","recycling"],"correctAnswer":"waste separation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I try to reduce my plastic consumption.","options":["Ich versuche, meinen Plastikverbrauch zu reduzieren.","Ich kaufe wenig Plastik.","Plastik ist schlecht.","Ich recycele Plastik."],"correctAnswer":"Ich versuche, meinen Plastikverbrauch zu reduzieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir kaufen ___ regionale Produkte.","options":["bevorzugt","gern","lieber","meistens"],"correctAnswer":"bevorzugt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She preferably buys second-hand clothes","wordBankItems":["Sie","kauft","bevorzugt","Second-Hand-Kleidung","."],"correctAnswer":"Sie kauft bevorzugt Second-Hand-Kleidung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verringern'' means?","options":["to reduce/diminish","to decrease","to lower","to cut"],"correctAnswer":"to reduce/diminish"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital life vocabulary","Talk about online activities","Use digital German vocabulary"],"explanation":{"intro":"Digital vocabulary is essential in modern life. A2 covers key online and social media terms.","culturalNote":"Germany has strict data protection laws (Datenschutz — GDPR originated partly from German law). Privacy (Privatsphäre) is very valued. Cookie consent, data minimisation, and right to be forgotten are active German concerns."},"examples":[{"german":"Ich poste selten auf Social Media — mir ist Datenschutz wichtig.","english":"I rarely post on social media — data protection is important to me."},{"german":"Ich mache regelmäßig Backups meiner Daten.","english":"I regularly back up my data."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss digital life and online topics in German."}}',
'{"items":[{"word":"der Datenschutz","translation":"data protection","pronunciation":"dayr DAH-ten-shoots","example":"Datenschutz beachten."},{"word":"die Privatsphäre","translation":"privacy","pronunciation":"dee pree-VAHT-sfä-reh","example":"Privatsphäre schützen."},{"word":"das Passwort","translation":"password","pronunciation":"dahs PAS-vort","example":"Sicheres Passwort wählen."},{"word":"die Datensicherheit","translation":"data security","pronunciation":"dee DAH-ten-zikh-er-hyt","example":"Datensicherheit wichtig."},{"word":"das Backup","translation":"backup","pronunciation":"dahs BAK-up","example":"Backup machen."},{"word":"posten","translation":"to post (online)","pronunciation":"POS-ten","example":"Auf Instagram posten."}]}',
'{"title":"Mir ist wichtig — it matters to me","pattern":"Mir ist [subject] wichtig / Mir ist es wichtig, dass...","explanation":"Mir ist wichtig = it matters to me / is important to me (dative). Mir ist Datenschutz wichtig = data protection matters to me. Mir ist es wichtig, dass... = It''s important to me that... The subject comes after ist: Mir ist die Privatsphäre wichtig. Alternative: Ich lege Wert auf (I attach importance to): Ich lege Wert auf Datenschutz.","examples":[{"sentence":"Mir ist es wichtig, ehrlich zu sein.","translation":"It is important to me to be honest."},{"sentence":"Ihm ist Pünktlichkeit sehr wichtig.","translation":"Punctuality matters a lot to him."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Datenschutz'' means?","options":["data protection","data security","privacy policy","data rights"],"correctAnswer":"data protection"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I rarely post on social media — data protection is important to me.","options":["Ich poste selten auf Social Media — mir ist Datenschutz wichtig.","Ich mag Social Media nicht.","Datenschutz ist wichtig.","Ich nutze Social Media selten."],"correctAnswer":"Ich poste selten auf Social Media — mir ist Datenschutz wichtig."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mir ist ___ wichtig, ehrlich zu sein.","options":["es","das","dies","sie"],"correctAnswer":"es"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Punctuality matters a lot to him","wordBankItems":["Ihm","ist","Pünktlichkeit","sehr","wichtig","."],"correctAnswer":"Ihm ist Pünktlichkeit sehr wichtig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Privatsphäre'' means?","options":["privacy","private life","personal space","personal data"],"correctAnswer":"privacy"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c7',1,'APPROVED','PUBLISHED',
'{"objectives":["Compare cultures","Express cultural observations","Use interkulturell vocabulary"],"explanation":{"intro":"Cross-cultural vocabulary is useful for anyone living in or interacting with German speakers from different backgrounds.","culturalNote":"Germany is a multicultural society with over 20% of residents having a migration background. Interkulturelles Verstehen (intercultural understanding) is taught in schools. Willkommenskultur (welcoming culture) debate has been active since 2015."},"examples":[{"german":"In meiner Heimatkultur geht man anders mit Zeit um.","english":"In my home culture one deals with time differently."},{"german":"Ich finde es interessant, wie unterschiedlich Begrüßungen sind.","english":"I find it interesting how different greetings are."}],"rewards":{"xp":130,"coins":65},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss and compare cultural differences in German."}}',
'{"items":[{"word":"interkulturell","translation":"intercultural","pronunciation":"in-ter-kool-too-REL","example":"Interkulturelle Unterschiede."},{"word":"umgehen mit","translation":"to deal with/handle","pronunciation":"OOM-gey-en mit","example":"Wie geht man damit um?"},{"word":"die Heimatkultur","translation":"home culture","pronunciation":"dee HY-maht-kool-toor","example":"Meine Heimatkultur."},{"word":"die Gewohnheit","translation":"habit/custom","pronunciation":"dee geh-VOHN-hyt","example":"Eine Gewohnheit haben."},{"word":"auffallen","translation":"to stand out/notice","pronunciation":"OWF-fal-en","example":"Das fällt mir auf."},{"word":"sich anpassen","translation":"to adapt","pronunciation":"zikh AN-pas-en","example":"Sich anpassen."}]}',
'{"title":"Mir fällt auf, dass — I notice that","pattern":"Mir fällt auf, dass + [verb-final clause]","explanation":"Auffallen (to notice/stand out): Mir fällt auf, dass... = I notice that... (dative mir). Das fällt mir auf = I notice that / that stands out to me. Negative: Das fällt mir nicht auf = I don''t notice that. Past: Das ist mir aufgefallen = I noticed that. Very useful for cultural observations.","examples":[{"sentence":"Mir fällt auf, dass Deutsche sehr direkt sind.","translation":"I notice that Germans are very direct."},{"sentence":"Es ist mir aufgefallen, dass man hier pünktlich sein muss.","translation":"I noticed that one must be punctual here."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sich anpassen'' means?","options":["to adapt","to adjust","to fit in","to conform"],"correctAnswer":"to adapt"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In my home culture one deals with time differently.","options":["In meiner Heimatkultur geht man anders mit Zeit um.","Meine Kultur ist anders.","Zeit ist anders in meiner Kultur.","Wir nutzen Zeit anders."],"correctAnswer":"In meiner Heimatkultur geht man anders mit Zeit um."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mir fällt auf, ___ Deutsche sehr direkt sind.","options":["dass","weil","ob","wenn"],"correctAnswer":"dass"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I notice that one must be punctual here","wordBankItems":["Mir","fällt","auf",",","dass","man","hier","pünktlich","sein","muss","."],"correctAnswer":"Mir fällt auf , dass man hier pünktlich sein muss ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Gewohnheit'' means?","options":["habit/custom","tradition","practice","routine"],"correctAnswer":"habit/custom"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000c8',1,'APPROVED','PUBLISHED',
'{"objectives":["Review all A2 grammar","Celebrate completing German A2","Look forward to B1"],"explanation":{"intro":"You have completed all 200 German lessons through A2! This is a major milestone — you can now communicate confidently in a wide range of everyday situations.","culturalNote":"A2 is the level required for family reunification visas in Germany. B1 is required for permanent residency (Niederlassungserlaubnis) and citizenship. Goethe-Institut and TestDaF offer official exams at each level."},"examples":[{"german":"Ich habe 200 Deutschlektionen abgeschlossen — das ist ein großer Erfolg!","english":"I have completed 200 German lessons — that is a great success!"},{"german":"Auf zu B1 — ich bin bereit für die nächste Herausforderung!","english":"On to B1 — I am ready for the next challenge!"}],"rewards":{"xp":250,"coins":150},"metadata":{"estimatedMinutes":20,"canDo":"I have completed German A1 and A2 — 200 lessons total!"}}',
'{"items":[{"word":"der Erfolg","translation":"success","pronunciation":"dayr er-FOLK","example":"Das ist ein Erfolg."},{"word":"abschließen","translation":"to complete/conclude","pronunciation":"AP-shlee-sen","example":"Einen Kurs abschließen."},{"word":"die Herausforderung","translation":"challenge","pronunciation":"dee her-OWS-for-der-oong","example":"Eine Herausforderung."},{"word":"bereit für","translation":"ready for","pronunciation":"beh-RYT FÜR","example":"Ich bin bereit."},{"word":"weiterkommen","translation":"to progress/move forward","pronunciation":"VY-ter-kom-en","example":"Ich komme weiter."},{"word":"stolz auf sich","translation":"proud of oneself","pronunciation":"SHTOLTS owf zikh","example":"Stolz auf sich sein."}]}',
'{"title":"Auf zu — onwards to (motivational phrase)","pattern":"Auf zu + [destination/goal]! (let''s go / onwards to!)","explanation":"Auf zu (onwards to / let''s go to) is a motivational phrase. Auf zu B1! = On to B1! Auf zu neuen Abenteuern! = On to new adventures! It combines auf (up/onward) and zu (to). Often used at transitions. Auf geht''s! = Let''s go! (general). Weiter geht''s! = Let''s continue!","examples":[{"sentence":"Auf zu neuen Ufern!","translation":"On to new shores! (new horizons)"},{"sentence":"Weiter geht''s mit dem nächsten Kapitel.","translation":"On we go with the next chapter."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Herausforderung'' means?","options":["challenge","obstacle","difficulty","test"],"correctAnswer":"challenge"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have completed 200 German lessons — that is a great success!","options":["Ich habe 200 Deutschlektionen abgeschlossen — das ist ein großer Erfolg!","Ich habe viel gelernt.","200 Lektionen sind abgeschlossen.","Ich bin fertig."],"correctAnswer":"Ich habe 200 Deutschlektionen abgeschlossen — das ist ein großer Erfolg!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Auf ___ B1 — ich bin bereit!","options":["zu","nach","bis","in"],"correctAnswer":"zu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: On to new shores!","wordBankItems":["Auf","zu","neuen","Ufern","!"],"correctAnswer":"Auf zu neuen Ufern !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"At what visa level is B1 German required for permanent residency?","options":["Niederlassungserlaubnis","Aufenthaltserlaubnis","Familiennachzug","Work visa"],"correctAnswer":"Niederlassungserlaubnis"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

